/**
 * Fetch wrapper with retries and exponential backoff.
 *
 * - Retries on network errors and 5xx responses; never on 4xx.
 * - Backoff: base delay (default 100ms) doubling per attempt, with full jitter
 *   (uniformly random in [0, computedDelay]).
 * - maxAttempts defaults to 4 (total attempts, including the first).
 * - A Retry-After header (seconds) on a retryable response overrides the
 *   computed backoff for that attempt (jitter is not applied to it).
 * - onRetry hook receives { attempt, delay, reason } before each retry sleep.
 *   `attempt` is the number of the attempt that just failed (1-based).
 */

const DEFAULTS = {
  maxAttempts: 4,
  baseDelayMs: 100,
};

function computeBackoff(attempt, baseDelayMs) {
  // Exponential: base * 2^(attempt - 1), capped at Number.MAX_SAFE_INTEGER.
  const exp = Math.min(attempt - 1, 30);
  const computed = baseDelayMs * 2 ** exp;
  // Full jitter: uniform in [0, computed].
  return Math.random() * computed;
}

function parseRetryAfter(response) {
  const raw = response.headers.get('retry-after');
  if (raw === null || raw === '') return null;
  const seconds = Number(raw);
  if (!Number.isNaN(seconds) && seconds >= 0) {
    return seconds * 1000;
  }
  // HTTP-date form is not supported for simplicity; ignore it.
  return null;
}

export async function refetch(url, opts = {}) {
  const { maxAttempts = DEFAULTS.maxAttempts, baseDelayMs = DEFAULTS.baseDelayMs, ...fetchOpts } = opts;

  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
    throw new TypeError('maxAttempts must be a positive integer');
  }
  if (!(baseDelayMs >= 0)) {
    throw new TypeError('baseDelayMs must be a non-negative number');
  }

  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    let response;
    try {
      response = await fetch(url, fetchOpts);
    } catch (err) {
      // Network-level error: retryable.
      lastError = err;
      if (attempt < maxAttempts) {
        const reason = `network error: ${err && err.message ? err.message : String(err)}`;
        const delay = computeBackoff(attempt, baseDelayMs);
        if (typeof opts.onRetry === 'function') opts.onRetry({ attempt, delay, reason });
        await new Promise((resolve) => setTimeout(resolve, delay));
        continue;
      }
      throw err;
    }

    if (response.status >= 200 && response.status < 400) {
      return response;
    }

    if (response.status >= 400 && response.status < 500) {
      // Client errors are never retried.
      return response;
    }

    // 5xx: retryable.
    lastError = Object.assign(new Error(`HTTP ${response.status} ${response.statusText}`), {
      response,
      status: response.status,
    });

    if (attempt < maxAttempts) {
      const override = parseRetryAfter(response);
      const reason = `HTTP ${response.status}`;
      const delay = override !== null ? override : computeBackoff(attempt, baseDelayMs);
      if (typeof opts.onRetry === 'function') opts.onRetry({ attempt, delay, reason });
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

export default refetch;

