import { createServer } from 'node:http';

/**
 * Test server with deterministic endpoints:
 *  - /flaky       : fails twice with 503, then 200 + JSON body
 *  - /always-400  : always returns 400
 *  - /retry-after : returns 503 with Retry-After: 1 once, then 200
 * Every endpoint increments a per-path hit counter.
 */
export function createTestServer() {
  const hits = Object.create(null);

  const server = createServer((req, res) => {
    const path = req.url ? req.url.split('?')[0] : '/';
    hits[path] = (hits[path] || 0) + 1;
    const hit = hits[path];

    res.setHeader('content-type', 'application/json');

    if (path === '/flaky') {
      if (hit <= 2) {
        res.statusCode = 503;
        res.end(JSON.stringify({ error: 'service unavailable', hit }));
      } else {
        res.statusCode = 200;
        res.end(JSON.stringify({ ok: true, hit }));
      }
      return;
    }

    if (path === '/always-400') {
      res.statusCode = 400;
      res.end(JSON.stringify({ error: 'bad request', hit }));
      return;
    }

    if (path === '/retry-after') {
      if (hit === 1) {
        res.setHeader('retry-after', '1');
        res.statusCode = 503;
        res.end(JSON.stringify({ error: 'try again later', hit }));
      } else {
        res.statusCode = 200;
        res.end(JSON.stringify({ ok: true, hit }));
      }
      return;
    }

    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'not found' }));
  });

  /**
   * Listen on an ephemeral port (0) and resolve with the base URL.
   */
  function listen() {
    return new Promise((resolve, reject) => {
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => resolve(`http://127.0.0.1:${server.address().port}`));
    });
  }

  async function close() {
    await new Promise((resolve, reject) => {
      server.close((err) => (err && err.code !== 'ERR_SERVER_NOT_RUNNING' ? reject(err) : resolve()));
    });
    // Ensure open keep-alive sockets don't hold the process open.
    server.closeAllConnections?.();
  }

  return { server, listen, close, hits };
}

export default createTestServer;

