import { describe, it, expect, afterAll } from 'vitest';
import { refetch } from '../src/refetch.js';
import { createTestServer } from './server.js';

const BASE_DELAY_MS = 10; // keep real delays short
const MAX_ATTEMPTS = 4;

let baseUrl;
const cleanupTasks = [];

async function startServer() {
  if (!baseUrl) {
    const app = createTestServer();
    baseUrl = await app.listen();
    cleanupTasks.push(() => app.close());
    return { app, url: baseUrl };
  }
  throw new Error('server already started');
}

afterAll(async () => {
  await Promise.all(cleanupTasks.map((fn) => fn()));
});

describe('refetch integration', () => {
  it('retries 5xx twice on /flaky then returns 200 JSON (3 total attempts)', async () => {
    const { app } = await startServer();

    const res = await refetch(`${baseUrl}/flaky`, { baseDelayMs: BASE_DELAY_MS });

    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body).toEqual({ ok: true, hit: 3 });
    // Server-side hit counter proves exactly 3 requests were made.
    expect(app.hits['/flaky']).toBe(3);
  });

  it('never retries 4xx (/always-400 gets exactly one request)', async () => {
    const { app } = await startServer();

    const res = await refetch(`${baseUrl}/always-400`, { baseDelayMs: BASE_DELAY_MS });

    expect(res.status).toBe(400);
    const body = await res.json();
    expect(body.hit).toBe(1); // single hit -> no retry
    expect(app.hits['/always-400']).toBe(1);
  });

  it('Retry-After header overrides computed backoff, observed via onRetry', async () => {
    const { app } = await startServer();

    const retries = [];
    const res = await refetch(`${baseUrl}/retry-after`, {
      baseDelayMs: BASE_DELAY_MS,
      onRetry: (info) => retries.push(info),
    });

    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body).toEqual({ ok: true, hit: 2 });
    expect(app.hits['/retry-after']).toBe(2);

    expect(retries).toHaveLength(1);
    // Server sent Retry-After: 1 -> override must be exactly 1000ms,
    // far above the 10ms-base exponential backoff (~<=20ms).
    expect(retries[0]).toEqual({ attempt: 1, delay: 1000, reason: 'HTTP 503' });
    expect(retries[0].delay).toBeGreaterThan(BASE_DELAY_MS * 4);
  });

  it('onRetry sees doubling-with-jitter backoff bounded by base * 2^(attempt-1)', async () => {
    const { app } = await startServer();

    const retries = [];
    await refetch(`${baseUrl}/flaky`, {
      baseDelayMs: BASE_DELAY_MS,
      onRetry: (info) => retries.push(info),
    });

    expect(retries.map((r) => r.attempt)).toEqual([1, 2]);
    expect(retries.every((r) => r.reason === 'HTTP 503')).toBe(true);
    // Full jitter: each delay is uniform in [0, base * 2^(attempt-1)].
    expect(retries[0].delay).toBeGreaterThanOrEqual(0);
    expect(retries[0].delay).toBeLessThanOrEqual(BASE_DELAY_MS * 2 ** 0 + 5);
    expect(retries[1].delay).toBeGreaterThanOrEqual(0);
    expect(retries[1].delay).toBeLessThanOrEqual(BASE_DELAY_MS * 2 ** 1 + 5);
    expect(app.hits['/flaky']).toBe(3);
  });

  it('retries network errors up to maxAttempts then throws', async () => {
    // Grab an address, then shut its server down so connections fail at the
    // network level (ECONNREFUSED) rather than producing HTTP responses.
    const dead = createTestServer();
    const deadUrl = await dead.listen();
    await dead.close();
    cleanupTasks.push(() => dead.close());

    const retries = [];
    await expect(
      refetch(`${deadUrl}/flaky`, {
        baseDelayMs: BASE_DELAY_MS,
        onRetry: (info) => retries.push(info),
      })
    ).rejects.toThrow();

    expect(retries).toHaveLength(MAX_ATTEMPTS - 1); // no retry after last attempt
    expect(retries.map((r) => r.attempt)).toEqual([1, 2, 3]);
    expect(retries.every((r) => r.reason.startsWith('network error'))).toBe(true);
  });

  it('respects a custom smaller maxAttempts', async () => {
    const { app } = await startServer();

    // /flaky needs 3 attempts; cap at 2 -> should surface the final 503.
    const retries = [];
    const res = await refetch(`${baseUrl}/flaky`, {
      baseDelayMs: BASE_DELAY_MS,
      maxAttempts: 2,
      onRetry: (info) => retries.push(info),
    });

    expect(res.status).toBe(503);
    expect(app.hits['/flaky']).toBe(2);
    expect(retries).toHaveLength(1);
  });
});

