// /flaky needs 3 attempts; cap at 2 -> should exhaust and throw with the
// final 503 attached.
const retries = [];
const err = await refetch(`${url}/flaky`, {
  baseDelayMs: BASE_DELAY_MS,
  maxAttempts: 2,
  onRetry: (info) => retries.push(info),
}).catch((e) => e);

expect(err).toBeInstanceOf(Error);
expect(err.status).toBe(503);
expect(app.hits['/flaky']).toBe(2);
expect(retries).toHaveLength(1);

